ALTER TABLE "filerfile" ADD COLUMN "path" VARCHAR(255) NOT NULL DEFAULT 'ungrouped';

-- (patch) filerfile: ensure index "idx_filerfile_path"
CREATE INDEX IF NOT EXISTS "idx_filerfile_path" ON "filerfile" ("path");
